export default function ({ events, previous, processedLabel, errorLabel }) {
  const items = events.filter(
      (x) => !x.labelIds.includes(processedLabel) && !x.labelIds.includes(errorLabel),
    ),
    i = (previous?.i ?? -1) + 1,
    m = items[i];
  return {
    state: { i },
    more: !!m,
    messageId: m?.messageId ?? "",
    to: m?.to ?? "",
    sender: m?.sender ?? "",
  };
}

