export default async function ({ to, messageId, base, table, token }, ctx) {
  const match = to.match(/\+(rec[a-zA-Z0-9]+)@/i);
  if (!match) return { status: "inactive", routeId: "" };
  const routeId = match[1];
  if ((await ctx.state.get("mail-task:" + messageId))?.status === "rejected")
    return { status: "rejected", routeId };
  const url = `https://api.airtable.com/v0/${encodeURIComponent(base)}/${encodeURIComponent(table)}/${encodeURIComponent(routeId)}`,
    r = await ctx.fetch(url, { headers: { Authorization: "Bearer " + token } });
  if (r.status === 404) return { status: "missing", routeId };
  if (!r.ok) throw Error("Route lookup failed");
  const b = await r.json();
  if (b.id !== routeId || typeof b.fields?.Active !== "boolean")
    throw Error("Invalid route record");
  return { status: b.fields.Active ? "active" : "inactive", routeId };
}

