export default async function ({ routeId, messageId, base, table, token, task, summary }, ctx) {
  const key = "mail-task:" + messageId,
    prev = await ctx.state.get(key);
  if (prev?.status === "pending") throw Error("Inspect Notion before retry");
  if (prev?.status === "done") return { status: "done", key };
  if (prev?.status === "rejected") return { status: "rejected", key };
  const url = `https://api.airtable.com/v0/${encodeURIComponent(base)}/${encodeURIComponent(table)}/${encodeURIComponent(routeId)}`,
    r = await ctx.fetch(url, { headers: { Authorization: "Bearer " + token } });
  if (!r.ok) throw Error("Route lookup failed");
  const row = await r.json();
  if (
    row.id !== routeId ||
    !row.fields?.Active ||
    !row.fields?.Token ||
    !row.fields?.NotionDatabase
  )
    throw Error("Route is inactive or incomplete");
  const match = String(row.fields.NotionDatabase).match(
    /([0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i,
  );
  if (!match) throw Error("Invalid Notion database ID");
  const rich = (s) => {
      const chars = Array.from(String(s)),
        out = [];
      for (let i = 0; i < chars.length; i += 1800)
        out.push({ type: "text", text: { content: chars.slice(i, i + 1800).join("") } });
      return out.length ? out : [{ type: "text", text: { content: "" } }];
    },
    blocks = [
      { object: "block", type: "paragraph", paragraph: { rich_text: rich(task.description) } },
      ...task.bulletpoints.map((x) => ({
        object: "block",
        type: "bulleted_list_item",
        bulleted_list_item: { rich_text: rich(x) },
      })),
      {
        object: "block",
        type: "paragraph",
        paragraph: { rich_text: rich("Email summary: " + summary.summary) },
      },
      {
        object: "block",
        type: "paragraph",
        paragraph: {
          rich_text: rich(
            [summary.meta.sender, summary.meta.subject, summary.meta.date].join("\n"),
          ),
        },
      },
    ],
    body = {
      parent: { database_id: match[1] },
      properties: { Name: { title: rich(task.title) } },
      children: blocks,
    };
  await ctx.state.set(key, { status: "pending" });
  const out = await ctx.fetch("https://api.notion.com/v1/pages", {
    method: "POST",
    headers: {
      Authorization: "Bearer " + row.fields.Token,
      "Notion-Version": "2022-06-28",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
  if (out.status === 401 || out.status === 403) {
    await ctx.state.set(key, { status: "rejected" });
    return { status: "rejected", key };
  }
  if (!out.ok) throw Error("Notion request failed or outcome unknown");
  const result = await out.json();
  if (!result.id) throw Error("Notion result unconfirmed");
  await ctx.state.set(key, { status: "done" });
  return { status: "done", key };
}

