export default async function ({ messageId, routeId, base, table, token }, ctx) {
  const key = "mail-disable:" + messageId,
    s = await ctx.state.get(key);
  if (s === "pending") throw Error("Inspect route before retry");
  if (s === "done") return { ok: true };
  const url = `https://api.airtable.com/v0/${encodeURIComponent(base)}/${encodeURIComponent(table)}/${encodeURIComponent(routeId)}`;
  await ctx.state.set(key, "pending");
  const r = await ctx.fetch(url, {
    method: "PATCH",
    headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
    body: JSON.stringify({ fields: { Active: false } }),
  });
  if (!r.ok) throw Error("Route update failed or outcome unknown");
  const b = await r.json();
  if (b.id !== routeId || b.fields?.Active !== false) throw Error("Route update unconfirmed");
  await ctx.state.set(key, "done");
  return { ok: true };
}

