export default async function ({ messageId, kind }, ctx) {
  const key = "mail-" + kind + ":" + messageId,
    p = await ctx.state.get(key);
  if (p === "pending") throw Error("Inspect previous operation before retry");
  if (p === "done") return { key, skip: true };
  await ctx.state.set(key, "pending");
  return { key, skip: false };
}

